Here is the commit message:
HID: intel-ish-hid: fix NULL-ptr-deref in
 ishtp_bus_remove_all_clients

During a warm reset flow, the cl->device pointer may be NULL if the
reset occurs while clients are still being enumerated. Accessing
cl->device->reference_count without a NULL check leads to a kernel panic.

This issue was identified during multi-unit warm reboot stress clycles.
Add a defensive NULL check for cl->device to ensure stability under
such intensive testing conditions.

KASAN: null-ptr-deref in range [0000000000000000-0000000000000007]
Workqueue: ish_fw_update_wq fw_reset_work_fn

Call Trace:
 ishtp_bus_remove_all_clients+0xbe/0x130 [intel_ishtp]
 ishtp_reset_handler+0x85/0x1a0 [intel_ishtp]
 fw_reset_work_fn+0x8a/0xc0 [intel_ish_ipc]

Fixes: 3703f53b99e4a ("HID: intel_ish-hid: ISH Transport layer")
Signed-off-by: Ryan Lin <ryan.lin@intel.com>
Signed-off-by: Jiri Kosina <jkosina@suse.com>

Here is the root cause:
The function `ishtp_bus_remove_all_clients` accesses `cl->device->reference_count` without verifying that `cl->device` is not NULL. During a warm reset, clients may still be enumerated, and the `cl->device` pointer can be NULL, leading to a null-pointer dereference (kernel panic).

Here is the patch:
  */
 void ishtp_bus_remove_all_clients(struct ishtp_device *ishtp_dev,
 				  bool warm_reset)
 {
 	struct ishtp_cl_device	*cl_device, *n;
 	struct ishtp_cl	*cl;
 	unsigned long	flags;

 	spin_lock_irqsave(&ishtp_dev->cl_list_lock, flags);
 	list_for_each_entry(cl, &ishtp_dev->cl_list, link) {
 		cl->state = ISHTP_CL_DISCONNECTED;
-		if (warm_reset && cl->device->reference_count)
+		if (warm_reset && cl->device && cl->device->reference_count)
 			continue;

 		/*
 		 * Wake any pending process. The waiter would check dev->state
 		 * and determine that it's not enabled already,
 		 * and will return error to its caller
 		 */
 		wake_up_interruptible(&cl->wait_ctrl_res);

 		/* Disband any pending read/write requests and free rb */
 		ishtp_cl_flush_queues(cl);

 		/* Remove all free and in_process rings, both Rx and Tx */
 		ishtp_cl_free_rx_ring(cl);
 		ishtp_cl_free_tx_ring(cl);

 		/*
 		 * Free client and ISHTP bus client device structures
 		 * don't free host client because it is part of the OS fd
 		 * structure
 		 */
 	}
 	spin_unlock_irqrestore(&ishtp_dev->cl_list_lock, flags);

 	/* Release DMA buffers for client messages */
 	ishtp_cl_free_dma_buf(ishtp_dev);

 	/* remove bus clients */
 	spin_lock_irqsave(&ishtp_dev->device_list_lock, flags);
 	list_for_each_entry_safe(cl_device, n, &ishtp_dev->device_list,
 				 device_link) {
 		cl_device->fw_client = NULL;
 		if (warm_reset && cl_device->reference_count)
 			continue;

 		list_del(&cl_device->device_link);
 		spin_unlock_irqrestore(&ishtp_dev->device_list_lock, flags);
 		ishtp_bus_remove_device(cl_device);
 		spin_lock_irqsave(&ishtp_dev->device_list_lock, flags);
 	}
 	spin_unlock_irqrestore(&ishtp_dev->device_list_lock, flags);

 	/* Free all client structures */
 	spin_lock_irqsave(&ishtp_dev->fw_clients_lock, flags);
 	kfree(ishtp_dev->fw_clients);
 	ishtp_dev->fw_clients = NULL;
 	ishtp_dev->fw_clients_num = 0;
 	ishtp_dev->fw_client_presentation_num = 0;
 	ishtp_dev->fw_client_index = 0;
 	bitmap_zero(ishtp_dev->fw_clients_map, ISHTP_CLIENTS_MAX);
 	spin_unlock_irqrestore(&ishtp_dev->fw_clients_lock, flags);
 }
 EXPORT_SYMBOL(ishtp_bus_remove_all_clients);


